CREATE OR REPLACE FUNCTION place_venues_link_booking_targets()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE booking_targets AS target
    SET venue_id = NEW.id
    WHERE target.target_kind = 'venue'
      AND target.city_id = NEW.city_id
      AND place_venue_key(target.display_name) = NEW.name_key
      AND target.venue_id IS DISTINCT FROM NEW.id;
    RETURN NEW;
END
$function$
;
CREATE OR REPLACE FUNCTION action_ledger_mark_stale_unknown(p_workspace_id uuid, stale_threshold interval DEFAULT '00:10:00'::interval)
 RETURNS TABLE(action_id uuid, workspace_id uuid)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    UPDATE action_ledger
    SET state = 'UNKNOWN',
        state_entered_at = now(),
        updated_at = now(),
        transition_count = transition_count + 1,
        previous_state = 'RUNNING'
    WHERE action_ledger.workspace_id = p_workspace_id
      AND state = 'RUNNING'
      AND state_entered_at < now() - stale_threshold
    RETURNING action_id, workspace_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION action_ledger_reconcile(target_action_id uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$

DECLARE
    current_state text;
    action_status text;
    v_action_kind text;
    community_status text;
    community_error_message text;
    outbox_status text;
    outbox_error_kind text;
    new_state text;
BEGIN
    -- Lock the ledger row.
    SELECT state INTO current_state
    FROM action_ledger
    WHERE action_id = target_action_id
    FOR UPDATE;

    -- Only reconcile UNKNOWN or RECONCILING actions.
    IF current_state IS NULL OR current_state NOT IN ('UNKNOWN', 'RECONCILING') THEN
        RETURN current_state;
    END IF;

    -- Transition to RECONCILING.
    IF current_state = 'UNKNOWN' THEN
        UPDATE action_ledger
        SET state = 'RECONCILING',
            state_entered_at = now(),
            updated_at = now(),
            transition_count = transition_count + 1,
            previous_state = 'UNKNOWN',
            reconciliation_count = reconciliation_count + 1
        WHERE action_id = target_action_id;
    END IF;

    -- Get the action's current status and kind.
    SELECT a.status, a.action_kind INTO action_status, v_action_kind
    FROM autopilot_actions AS a
    WHERE a.id = target_action_id;

    -- Strategy 1: Check if the action status has been updated.
    IF action_status = 'succeeded' THEN
        new_state := 'SUCCEEDED';
    ELSIF action_status = 'failed' THEN
        new_state := 'FAILED';
    ELSIF v_action_kind = 'community.engage.request' THEN
        -- Strategy 2: For community engagement, check community_posts.
        SELECT status, error_message INTO community_status, community_error_message
        FROM community_posts
        WHERE action_id = target_action_id
        LIMIT 1;

        IF community_status = 'posted' THEN
            new_state := 'SUCCEEDED';
        ELSIF community_status = 'failed' THEN
            IF community_error_message IS NOT NULL
               AND community_error_message LIKE 'worker crashed during posting%' THEN
                new_state := 'UNKNOWN';
            ELSE
                new_state := 'FAILED';
            END IF;
        ELSE
            new_state := 'UNKNOWN';
        END IF;
    ELSE
        -- Strategy 3: For non-community actions, check the outbox event's
        -- delivery status as external truth. This is the authoritative
        -- reconciliation for actions that entered UNKNOWN because of
        -- ambiguous transport failures.
        SELECT e.status, e.last_error_kind INTO outbox_status, outbox_error_kind
        FROM outbox_events e
        WHERE e.action_id = target_action_id
        ORDER BY e.created_at DESC
        LIMIT 1;

        IF outbox_status = 'delivered' THEN
            -- The webhook was eventually delivered — the side effect happened.
            new_state := 'SUCCEEDED';
        ELSIF outbox_status = 'dead' THEN
            -- Check the error kind to distinguish permanent from ambiguous.
            IF outbox_error_kind IS NOT NULL AND (
                outbox_error_kind LIKE 'http_permanent%'
                OR outbox_error_kind = 'recipient_ineligible'
                OR outbox_error_kind LIKE 'secret_%'
                OR outbox_error_kind LIKE 'endpoint_%'
                OR outbox_error_kind = 'invalid_signing_secret'
                OR outbox_error_kind = 'event_serialization'
            ) THEN
                -- Permanent rejection — definitively failed.
                new_state := 'FAILED';
            ELSE
                -- Ambiguous error (transport_timeout, transport_request,
                -- lease_expired) — stay UNKNOWN. Only external truth from
                -- the provider can resolve this.
                new_state := 'UNKNOWN';
            END IF;
        ELSE
            -- Pending/processing or no outbox event — remain UNKNOWN.
            new_state := 'UNKNOWN';
        END IF;
    END IF;

    -- Apply the reconciliation result.
    IF new_state IN ('SUCCEEDED', 'FAILED', 'CANCELLED') THEN
        -- Write the SOURCE, not the projection. `autopilot_actions`
        -- is the primary record of operational state and
        -- `action_ledger` is a trigger-maintained projection of it
        -- (`autopilot_actions_ledger_sync`, AFTER UPDATE OF status).
        -- Updating the action lets that trigger carry the resolution into the
        -- ledger, which keeps the projection one-way.
        --
        -- `finished_at` is restored because the status CHECK requires it to be
        -- non-NULL for the terminal statuses, and the path that marked the
        -- action `unknown` clears it.
        UPDATE autopilot_actions
        SET status = CASE new_state
                         WHEN 'SUCCEEDED' THEN 'succeeded'
                         WHEN 'FAILED' THEN 'failed'
                         WHEN 'CANCELLED' THEN 'cancelled'
                     END,
            finished_at = COALESCE(finished_at, now()),
            updated_at = now()
        WHERE id = target_action_id;
    ELSE
        -- Still UNKNOWN — transition back from RECONCILING.
        UPDATE action_ledger
        SET state = 'UNKNOWN',
            state_entered_at = now(),
            updated_at = now(),
            transition_count = transition_count + 1,
            previous_state = 'RECONCILING'
        WHERE action_id = target_action_id;
    END IF;

    RETURN new_state;
END;
$function$
;
CREATE OR REPLACE FUNCTION action_ledger_sync()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    new_ledger_state text;
    current_ledger_state text;
BEGIN
    -- Map the action status to the ledger state.
    new_ledger_state := CASE NEW.status
        WHEN 'awaiting_approval' THEN 'AUTHORIZED'
        WHEN 'queued' THEN 'QUEUED'
        WHEN 'processing' THEN 'RUNNING'
        WHEN 'succeeded' THEN 'SUCCEEDED'
        WHEN 'failed' THEN 'FAILED'
        WHEN 'cancelled' THEN 'CANCELLED'
        WHEN 'unknown' THEN 'UNKNOWN'
        ELSE NULL
    END;

    -- If the status doesn't map to a ledger state, skip.
    IF new_ledger_state IS NULL THEN
        RETURN NEW;
    END IF;

    -- Check if a ledger entry already exists.
    SELECT state INTO current_ledger_state
    FROM action_ledger
    WHERE action_id = NEW.id
    FOR UPDATE;

    IF current_ledger_state IS NULL THEN
        -- Insert a new ledger entry.
        INSERT INTO action_ledger
            (action_id, workspace_id, state, trace_id, causation_id, decision_id,
             state_entered_at, transition_count, previous_state)
        VALUES
            (NEW.id, NEW.workspace_id, new_ledger_state, NEW.trace_id,
             NEW.causation_id, NEW.decision_id, now(), 0, NULL);
    ELSIF current_ledger_state = new_ledger_state THEN
        -- No state change — just update trace_id/causation_id if they were NULL.
        UPDATE action_ledger
        SET trace_id = COALESCE(action_ledger.trace_id, NEW.trace_id),
            causation_id = COALESCE(action_ledger.causation_id, NEW.causation_id),
            updated_at = now()
        WHERE action_id = NEW.id;
    ELSE
        -- State transition — enforce the monotonic state machine.
        -- RUNNING → QUEUED is allowed for retryable failures (fail_action
        -- sets status back to 'queued' when attempt_count < 5).
        IF NOT (
            (current_ledger_state = 'PLANNED' AND new_ledger_state IN ('AUTHORIZED', 'CANCELLED', 'REVOKED'))
            OR (current_ledger_state = 'AUTHORIZED' AND new_ledger_state IN ('QUEUED', 'CANCELLED', 'REVOKED'))
            OR (current_ledger_state = 'QUEUED' AND new_ledger_state IN ('RUNNING', 'CANCELLED', 'FAILED'))
            OR (current_ledger_state = 'RUNNING' AND new_ledger_state IN ('SUCCEEDED', 'FAILED', 'UNKNOWN', 'QUEUED'))
            OR (current_ledger_state = 'UNKNOWN' AND new_ledger_state IN ('RECONCILING', 'SUCCEEDED', 'FAILED'))
            OR (current_ledger_state = 'RECONCILING' AND new_ledger_state IN ('SUCCEEDED', 'FAILED', 'UNKNOWN'))
            OR (current_ledger_state = 'SUCCEEDED' AND new_ledger_state IN ('FAILED', 'UNKNOWN'))
        ) THEN
            RAISE EXCEPTION 'Action ledger: illegal transition from % to % for action %',
                current_ledger_state, new_ledger_state, NEW.id
                USING ERRCODE = 'check_violation';
        END IF;

        -- Apply the transition.
        UPDATE action_ledger
        SET state = new_ledger_state,
            state_entered_at = now(),
            updated_at = now(),
            transition_count = transition_count + 1,
            previous_state = current_ledger_state,
            trace_id = COALESCE(action_ledger.trace_id, NEW.trace_id),
            causation_id = COALESCE(action_ledger.causation_id, NEW.causation_id)
        WHERE action_id = NEW.id;
    END IF;

    RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION attestations_are_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
       OR NEW.act_name IS DISTINCT FROM OLD.act_name
       OR NEW.figures IS DISTINCT FROM OLD.figures
       OR NEW.issued_at IS DISTINCT FROM OLD.issued_at
       OR NEW.valid_until IS DISTINCT FROM OLD.valid_until
       OR NEW.digest IS DISTINCT FROM OLD.digest
       OR NEW.signature IS DISTINCT FROM OLD.signature
    THEN
        RAISE EXCEPTION
            'an issued attestation cannot be edited; issue a new one instead'
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END
$function$
;
CREATE OR REPLACE FUNCTION booking_targets_resolve_venue()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    resolved uuid;
BEGIN
    IF NEW.target_kind <> 'venue' THEN
        NEW.venue_id := NULL;
        RETURN NEW;
    END IF;

    SELECT venue.id INTO resolved
    FROM place_venues AS venue
    WHERE venue.city_id = NEW.city_id
      AND venue.name_key = place_venue_key(NEW.display_name);

    -- `resolved` is NULL when the room is not in the registry, and assigning
    -- NULL is the point: a target whose room was renamed out of a match loses
    -- the stale link rather than keeping a claim that no longer holds.
    NEW.venue_id := resolved;
    RETURN NEW;
END
$function$
;
CREATE OR REPLACE FUNCTION project_event_content_sources()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.status IN ('published','completed') THEN
        INSERT INTO content_sources(
            id,workspace_id,source_kind,source_key,title,occurred_at,expires_at,metadata,active
        ) VALUES(
            NEW.id,NEW.workspace_id,'event','event:' || NEW.id::text,NEW.title,now(),
            GREATEST(NEW.starts_at + INTERVAL '14 days', now() + INTERVAL '7 days'),
            jsonb_build_object('event_id',NEW.id,'slug',NEW.slug,'venue',NEW.venue,'starts_at',NEW.starts_at,'city_id',NEW.city_id),true
        )
        ON CONFLICT(workspace_id,source_kind,source_key) DO UPDATE SET
            title=EXCLUDED.title,
            expires_at=GREATEST(content_sources.expires_at, NEW.starts_at + INTERVAL '14 days'),
            metadata=EXCLUDED.metadata,
            active=true,version=content_sources.version+1
        WHERE content_sources.title IS DISTINCT FROM EXCLUDED.title
           OR content_sources.metadata IS DISTINCT FROM EXCLUDED.metadata
           OR content_sources.active IS DISTINCT FROM true
           OR content_sources.expires_at IS DISTINCT FROM
              GREATEST(content_sources.expires_at, NEW.starts_at + INTERVAL '14 days');
    ELSE
        UPDATE content_sources
        SET active=false,version=version+1
        WHERE workspace_id=NEW.workspace_id AND source_kind='event' AND source_key='event:' || NEW.id::text AND active;
    END IF;

    IF NEW.status = 'completed' THEN
        IF TG_OP = 'INSERT'
           OR (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM 'completed') THEN
            INSERT INTO content_sources(
                workspace_id,source_kind,source_key,title,occurred_at,expires_at,metadata,active
            ) VALUES(
                NEW.workspace_id,'show_completed','show_completed:' || NEW.id::text,NEW.title,now(),now()+INTERVAL '45 days',
                jsonb_build_object('event_id',NEW.id,'slug',NEW.slug,'venue',NEW.venue,'starts_at',NEW.starts_at,'city_id',NEW.city_id),true
            )
            ON CONFLICT(workspace_id,source_kind,source_key) DO UPDATE SET
                title=EXCLUDED.title,metadata=EXCLUDED.metadata,expires_at=EXCLUDED.expires_at,
                active=true,version=content_sources.version+1;
        END IF;
    END IF;
    RETURN NEW;
END
$function$
;
CREATE OR REPLACE FUNCTION project_release_content_sources()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- The same forty-five-day window the backfill applies: a plan whose
    -- release window already closed (reactivated history, a date pushed far
    -- into the past) would project a source the evaluator can only ever hold
    -- as stale, so it projects nothing at all.
    IF NEW.active AND NEW.release_at > now() - INTERVAL '45 days' THEN
        INSERT INTO content_sources(
            id,workspace_id,source_kind,source_key,title,occurred_at,expires_at,metadata,active
        ) VALUES(
            NEW.id,NEW.workspace_id,'release','release:' || NEW.id::text,NEW.title,NEW.release_at,
            NEW.release_at + INTERVAL '45 days',
            jsonb_build_object('release_plan_id',NEW.id,'source_key',NEW.source_key,
                'release_at',NEW.release_at,'listen_url',NEW.listen_url,
                'assets_ready',NEW.assets_ready,'tier',NEW.tier,
                'communication_enabled',NEW.communication_enabled,
                'press_enabled',NEW.press_enabled),true
        )
        ON CONFLICT(workspace_id,source_kind,source_key) DO UPDATE SET
            title=EXCLUDED.title,
            occurred_at=EXCLUDED.occurred_at,
            expires_at=EXCLUDED.expires_at,
            metadata=EXCLUDED.metadata,
            active=true,version=content_sources.version+1
        WHERE content_sources.title IS DISTINCT FROM EXCLUDED.title
           OR content_sources.occurred_at IS DISTINCT FROM EXCLUDED.occurred_at
           OR content_sources.expires_at IS DISTINCT FROM EXCLUDED.expires_at
           OR content_sources.metadata IS DISTINCT FROM EXCLUDED.metadata
           OR content_sources.active IS DISTINCT FROM true;
    ELSE
        UPDATE content_sources
        SET active=false,version=version+1
        WHERE workspace_id=NEW.workspace_id AND source_kind='release'
          AND source_key='release:' || NEW.id::text AND active;
    END IF;
    RETURN NEW;
END
$function$
;
CREATE OR REPLACE FUNCTION provision_autopilot_policies()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    INSERT INTO autopilot_policies
        (workspace_id, context, max_actions_24h, enabled, autonomy_level,
         minimum_confidence_basis_points)
    VALUES
        -- Drafting, discovery, measurement: unattended.
        (NEW.id, 'growth_intelligence', 30, true, 'bounded_auto', 8000),
        (NEW.id, 'outreach_supply', 2, true, 'bounded_auto', 8000),
        (NEW.id, 'content_supply', 30, true, 'bounded_auto', 8000),
        (NEW.id, 'growth_metrics', 12, true, 'bounded_auto', 8000),
        (NEW.id, 'growth_debt', 10, true, 'bounded_auto', 8000),
        -- Spends money.
        (NEW.id, 'ticket_yield', 10, true, 'require_approval', 8000),
        (NEW.id, 'merchandising', 20, true, 'require_approval', 8000),
        (NEW.id, 'merch_pricing', 10, true, 'require_approval', 8000),
        (NEW.id, 'merch_bundle', 5, true, 'require_approval', 8000),
        (NEW.id, 'promotion_budget', 20, true, 'require_approval', 8000),
        (NEW.id, 'funding', 10, true, 'require_approval', 8000),
        -- Contacts a person.
        (NEW.id, 'fan_lifecycle', 100, true, 'require_approval', 8000),
        (NEW.id, 'outreach', 20, true, 'require_approval', 8000),
        (NEW.id, 'beacon', 12, true, 'require_approval', 8000),
        -- The organisation's own rail: the weekly brief writes to a
        -- manager's inbox, so it sits with the person-contacting family
        -- rather than the unattended measurement rows.
        (NEW.id, 'roster', 10, true, 'require_approval', 8000),
        -- The band approaching an agent or a label — brokered, hidden
        -- address, scarce by the month.
        (NEW.id, 'representation', 4, true, 'require_approval', 5000),
        -- The band approaching a booking agent for representation —
        -- scarcer still: one letter per agent a season, and the evidence
        -- gate binds harder than this cap ever will.
        (NEW.id, 'booking_agent', 2, true, 'require_approval', 5000),
        -- Publishes or commits.
        (NEW.id, 'campaign_lifecycle', 20, true, 'require_approval', 8000),
        (NEW.id, 'release', 30, true, 'require_approval', 8000),
        (NEW.id, 'booking_opportunity', 10, true, 'require_approval', 8000),
        (NEW.id, 'live_opportunity', 15, true, 'require_approval', 8000),
        (NEW.id, 'show_operations', 50, true, 'require_approval', 8000),
        (NEW.id, 'show_growth', 14, true, 'require_approval', 8000),
        (NEW.id, 'experimentation', 10, true, 'require_approval', 8000),
        (NEW.id, 'plays', 40, true, 'require_approval', 8000),
        -- The band decides what it makes. Creative work stays human in
        -- every posture: the engine proposes, the band commits. The 5000
        -- floor matches the evaluator's evidence-derived confidence — a
        -- bare raise scores 6000 — where the inherited 8000 default would
        -- deny most of what the engine ranked.
        (NEW.id, 'content_strategy', 6, true, 'require_approval', 5000)
    ON CONFLICT (workspace_id, context) DO NOTHING;
    RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION provision_growth_autonomy()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    INSERT INTO growth_autonomy (workspace_id, action_class, ceiling, rationale)
    VALUES
        (NEW.id, 'first_party_reversible', 'bounded_auto',
         'costs nothing, reaches nobody outside the workspace, undone by doing the opposite'),
        (NEW.id, 'owned_audience', 'bounded_auto',
         'reaches fans who opted in; free, but a sent message cannot be unsent'),
        (NEW.id, 'third_party', 'require_approval',
         'the band gets one first approach to each venue, curator or press contact'),
        (NEW.id, 'paid', 'require_approval',
         'moves money and cannot be recovered by changing our minds')
    ON CONFLICT (workspace_id, action_class) DO NOTHING;
    RETURN NEW;
END;
$function$
;
