CREATE OR REPLACE FUNCTION rebuild_growth_episodes_from_evidence(p_workspace_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    inserted_count integer;
BEGIN
    -- Truncate existing episodes for the workspace (or all if NULL).
    IF p_workspace_id IS NOT NULL THEN
        DELETE FROM growth_episodes WHERE workspace_id = p_workspace_id;
    ELSE
        TRUNCATE TABLE growth_episodes;
    END IF;

    -- Rebuild from the source-of-truth evidence table.
    INSERT INTO growth_episodes (
        workspace_id, action_id, opportunity_id, episode_id,
        channel, estimated_reach, treatment, propensity,
        predicted_fans, predicted_signal_installs, context,
        observed_fans, observed_incremental_fans, durable_fans_30d,
        actual_reach, converted, resolved_at, updated_at
    )
    SELECT
        ge.workspace_id,
        ge.action_id,
        ge.opportunity_id,
        ge.episode_id,
        ge.channel,
        ge.estimated_reach,
        ge.treatment,
        ge.propensity,
        ge.predicted_fans,
        ge.predicted_signal_installs,
        ge.context,
        ge.observed_fans,
        ge.observed_incremental_fans,
        ge.durable_fans_30d,
        ge.actual_reach,
        ge.converted,
        ge.resolved_at,
        now()
    FROM growth_evidence ge
    WHERE p_workspace_id IS NULL OR ge.workspace_id = p_workspace_id;

    GET DIAGNOSTICS inserted_count = ROW_COUNT;

    RETURN inserted_count;
END;
$function$
;
CREATE OR REPLACE FUNCTION seed_release_playlist_outreach()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.milestone <> 'start_press' THEN
        RETURN NEW;
    END IF;

    INSERT INTO outreach_opportunities (
        workspace_id,
        target_id,
        source,
        subject_kind,
        subject_key,
        template_key,
        relevance_basis_points,
        confidence_basis_points,
        active,
        observed_at,
        expires_at
    )
    SELECT
        target.workspace_id,
        target.id,
        'release_autopilot',
        'release',
        format('release:%s', NEW.release_id),
        'release.playlist.v1',
        GREATEST(7_500, LEAST(10_000, target.relationship_score * 100)),
        9_200,
        true,
        NEW.completed_at,
        GREATEST(plan.release_at + INTERVAL '14 days', NEW.completed_at + INTERVAL '14 days')
    FROM outreach_targets AS target
    JOIN release_plans AS plan
      ON plan.workspace_id = NEW.workspace_id
     AND plan.id = NEW.release_id
    WHERE target.workspace_id = NEW.workspace_id
      AND target.target_kind = 'playlist'
      AND target.active
      AND target.verified
      AND target.accepts_outreach
      AND NOT target.do_not_contact
    ON CONFLICT (workspace_id, source, target_id, subject_kind, subject_key)
    DO UPDATE SET
        template_key = EXCLUDED.template_key,
        relevance_basis_points = EXCLUDED.relevance_basis_points,
        confidence_basis_points = EXCLUDED.confidence_basis_points,
        active = true,
        observed_at = EXCLUDED.observed_at,
        expires_at = EXCLUDED.expires_at;

    RETURN NEW;
END;
$function$
;
